'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hdPromise=Promise.resolve(window.OFFLINE_DATA.hdMedia);
const videos={realistic:['辛巴门徒 · 写实 AI 预告'],animated:['授业之战 · 卡通动画正片'],coronation:['门徒加冕 · 真实仪式'],march:['金狮点将 · 真实仪式']};
const dialog=$('#media-dialog'),content=$('#dialog-content');let lastFocus=null,mediaRevision=0;
function stopStream(){content.querySelector('video')?.pause();}
$('.menu-button').addEventListener('click',()=>{const open=$('.site-header nav').classList.toggle('open');$('.menu-button').setAttribute('aria-expanded',String(open));});
$('.site-header nav').addEventListener('click',()=>{$('.site-header nav').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');});
function show(title){stopStream();mediaRevision++;if(!dialog.open)lastFocus=document.activeElement;$('#dialog-title').textContent=title;content.replaceChildren();$('.gallery-controls').hidden=true;$('#image-zoom').hidden=true;$('#image-zoom').setAttribute('aria-pressed','false');$('#image-zoom').textContent='查看原尺寸';dialog.showModal();document.body.style.overflow='hidden';$('#dialog-close').focus();}
async function imageViewer(item){show(item.title);const revision=mediaRevision;const hd=await hdPromise;if(!dialog.open||revision!==mediaRevision)return;const name=(item.hdSrc||item.src)?.split('/').at(-1)?.replace('.webp','');const original=hd?.images[name];const img=document.createElement('img');img.className='detail-image';const source=item.hdSrc||original?.src||item.src;const toolbar=document.createElement('div');toolbar.className='video-quality';const status=document.createElement('span');toolbar.append(status);if(item.time!==undefined){const play=document.createElement('button');play.type='button';play.textContent='▶ 播放这一刻';play.addEventListener('click',()=>videoViewer(item.video||(item.src.includes('real-frame-')?'realistic':'animated'),item.time));toolbar.append(play);}img.addEventListener('load',()=>{status.textContent=`高清画面 · ${img.naturalWidth} × ${img.naturalHeight}`;});if(original?.creation){let creation=false;const button=document.createElement('button');button.type='button';button.textContent='查看创作原图';button.addEventListener('click',()=>{creation=!creation;img.src=creation?original.creation.src:source;img.alt=item.title+(creation?' · 创作原图':' · 成片画面');button.textContent=creation?'返回成片画面':'查看创作原图';$('#dialog-title').textContent=item.title+(creation?' · 创作原图':'');});toolbar.append(button);}img.src=source;img.alt=item.title;content.append(toolbar,img);$('#image-zoom').hidden=false;}
async function videoViewer(key,time=0){
  const info=videos[key];if(!info)return;galleryItems=[];show(info[0]);const revision=mediaRevision;const hd=await hdPromise;if(!dialog.open||revision!==mediaRevision)return;
  const video=document.createElement('video');video.className='dialog-video';video.controls=true;video.playsInline=true;video.preload='metadata';video.setAttribute('aria-label',info[0]);
  const toolbar=document.createElement('div');toolbar.className='video-quality';const status=document.createElement('span');const switcher=document.createElement('button');switcher.type='button';toolbar.append(status,switcher);content.append(toolbar,video);
  let isHd=true,start=time,usingFallback=false;
  const fallback=()=>{if(isHd&&hd?.videos[key]?.smoothSrc&&hd.videos[key].smoothSrc!==hd.videos[key].src){load(false,video.currentTime||start,!video.paused);return;}stopStream();usingFallback=true;status.textContent='视频暂时无法加载，请重新打开。';};
  const load=(high,position,play=false)=>{
    stopStream();start=position;isHd=high;usingFallback=false;
    const seek=()=>{if(start&&Math.abs(video.currentTime-start)>1)video.currentTime=start;};video.onloadedmetadata=seek;video.oncanplay=()=>{seek();video.oncanplay=null;if(play)video.play().catch(()=>{});};
    status.textContent=high?'1080P 高清':'流畅播放';switcher.textContent=high?'切换流畅':'切换1080P高清';
    const stream=hd?.videos[key],src=high?stream?.src:stream?.smoothSrc;switcher.hidden=!stream?.smoothSrc||stream.smoothSrc===stream.src;
    if(!src){fallback();return;}
    video.src=src;video.load();
  };
  switcher.addEventListener('click',()=>load(!isHd,video.currentTime,!video.paused));video.addEventListener('error',()=>{if(!usingFallback){fallback();return;}status.textContent='视频暂时无法加载，请重新打开。';});load(true,time,true);
}
function toggleImageZoom(){const img=content.querySelector('img');if(!img)return;const actual=img.classList.toggle('actual');$('#image-zoom').setAttribute('aria-pressed',String(actual));$('#image-zoom').textContent=actual?'适合窗口':'查看原尺寸';}
$('#image-zoom').addEventListener('click',toggleImageZoom);content.addEventListener('click',e=>{if(e.target.matches('.detail-image'))toggleImageZoom();});
$('#dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{mediaRevision++;content.querySelector('video')?.pause();stopStream();content.replaceChildren();document.body.style.overflow='';lastFocus?.focus();});dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
document.addEventListener('click',e=>{const v=e.target.closest('[data-video]');if(v){videoViewer(v.dataset.video,Number(v.dataset.time)||0);return;}const b=e.target.closest('[data-image-src]');if(b){galleryItems=[];imageViewer({title:b.dataset.title,src:b.dataset.imageSrc});}});
let galleryItems=[],galleryIndex=0;const galleries=new Map();
function registerGallery(key,items){galleries.set(key,items);return key;}
async function openGallery(items,index=0){galleryItems=items;galleryIndex=index;await imageViewer(items[index]);if(!dialog.open||galleryItems!==items)return;$('.gallery-controls').hidden=items.length<2;$('#gallery-count').textContent=`${index+1} / ${items.length}`;}
$('#gallery-prev').addEventListener('click',()=>openGallery(galleryItems,(galleryIndex+galleryItems.length-1)%galleryItems.length));
$('#gallery-next').addEventListener('click',()=>openGallery(galleryItems,(galleryIndex+1)%galleryItems.length));
document.addEventListener('keydown',e=>{if(dialog.open&&galleryItems.length>1&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();openGallery(galleryItems,(galleryIndex+(e.key==='ArrowRight'?1:-1)+galleryItems.length)%galleryItems.length);}if(e.key==='Escape'){$('.site-header nav').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-gallery]');if(b)openGallery(galleries.get(b.dataset.gallery),Number(b.dataset.index)||0);});
function timecode(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function shotCard(shot,key,gallery,index,featured=false){return `<article class="shot-card ${featured?'shot-featured':''}"><button class="shot-screen" data-video="${key}" data-time="${shot.time}" aria-label="从 ${timecode(shot.time)} 播放${esc(shot.title)}"><img src="${shot.src}" alt="${esc(shot.title)}" loading="lazy"><span class="play-ring">▶</span></button><div class="shot-label"><span><small>${timecode(shot.time)}</small>${esc(shot.title)}</span><button data-gallery="${gallery}" data-index="${index}" aria-label="放大${esc(shot.title)}">放大 ↗</button></div></article>`;}
function selected(group,value,attr){if(!group)return;group.querySelectorAll('[role=tab]').forEach(b=>{const active=b.dataset[attr]===String(value);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});}
function galleryButton(item,key,index,cls=''){return `<button class="${cls}" data-gallery="${key}" data-index="${index}" aria-label="放大${esc(item.title)}"><img src="${item.src}" alt="${esc(item.title)}" loading="lazy"></button>`;}
Promise.resolve(window.OFFLINE_DATA.siteData).then(data=>{
 function renderRealAct(i){const act=data.realisticActs[i],key=registerGallery('real-act-'+i,act.shots);selected($('.real-act-tabs'),i,'realAct');$('#realistic-shots').setAttribute('aria-labelledby','real-act-'+i);$('#realistic-shots').innerHTML=`<div class="real-act-intro"><span class="eyebrow">${esc(act.chapter)}</span><h4>${esc(act.name)}</h4><p>${esc(act.desc)}</p><button class="text-link" data-video="realistic" data-time="${act.start}">▶ 从这一幕观看</button></div><div class="real-mosaic real-mosaic-${i+1}">${act.shots.map((s,j)=>`<article class="shot-card" data-position="${j}"><button class="shot-screen" data-video="realistic" data-time="${s.time}" aria-label="从 ${timecode(s.time)} 播放${esc(s.title)}"><img src="${s.src}" srcset="${s.src} 700w, ${s.hdSrc} ${s.dimensions[0]}w" sizes="(max-width:650px) ${j===0?90:43}vw, ${j===0?38:24}vw" width="${s.dimensions[0]}" height="${s.dimensions[1]}" alt="${esc(s.title)}" style="object-position:${s.position}" loading="lazy"><span class="play-ring">▶</span></button><div class="shot-label"><span><small>${timecode(s.time)}</small>${esc(s.title)}</span><button data-gallery="${key}" data-index="${j}" aria-label="放大${esc(s.title)}">放大 ↗</button></div></article>`).join('')}</div><div class="real-act-navigation"><button class="text-link" data-real-select="${(i+data.realisticActs.length-1)%data.realisticActs.length}">上一组</button><span>0${i+1} / 0${data.realisticActs.length}</span><button class="text-link" data-real-select="${(i+1)%data.realisticActs.length}">下一组</button></div>`;}
 function renderAct(i){const act=data.acts[i],key=registerGallery('act-'+i,act.shots);selected($('.act-tabs'),i,'act');$('#act-panel').setAttribute('aria-labelledby','act-'+i);$('#act-panel').innerHTML=`<div class="act-layout"><div class="act-copy"><span class="eyebrow">ACT 0${i+1} / ${act.range}</span><h3>${esc(act.title)}</h3><p>${esc(act.desc)}</p><div class="direction"><b>导演与视觉表达</b><p>${esc(act.direction)}</p></div><button class="text-link" data-video="animated" data-time="${act.start}">▶ 从这一幕观看</button></div>${shotCard(act.shots[0],'animated',key,0,true)}<div class="shot-thumbnails">${act.shots.slice(1).map((s,j)=>shotCard(s,'animated',key,j+1)).join('')}</div></div>`;}
 function renderRoles(route,target='#role-grid'){$(target).innerHTML=data.roles[route].map((r,i)=>{const items=r.extras||[{title:r.title,src:r.src}],key=registerGallery('role-'+route+'-'+i,items);return `<article class="role-card"><button class="role-art" data-gallery="${key}" data-index="0" aria-label="放大${esc(r.title)}"><img src="${r.src}" alt="${esc(r.title)} · 完整设定图" loading="lazy"><span>查看完整设定 ↗</span></button><div class="role-copy"><div><h3>${esc(r.title)}</h3><span>${esc(r.sub)}</span></div><p>${esc(r.desc)}</p></div>${r.extras?`<div class="role-variants">${items.map((it,j)=>`<button data-gallery="${key}" data-index="${j}">${esc(it.title)} ↗</button>`).join('')}</div>`:''}</article>`;}).join('');}
 function renderSpace(i){const s=data.spaces[i],items=s.extras||data.spaces.map(s=>({title:s.title,src:s.src})),key=registerGallery('space-'+i,items),index=s.extras?0:i;selected($('.space-steps'),i,'space');$('#space-stage').setAttribute('role','tabpanel');$('#space-stage').setAttribute('aria-labelledby','space-step-'+i);$('#space-stage').innerHTML=`<div class="space-image">${galleryButton({title:s.title,src:s.src},key,index)}<span>查看完整画面 ↗</span></div><div class="space-copy"><span class="eyebrow">${s.tag}</span><h3>${s.title}</h3><p>${s.desc}</p>${s.video?`<button class="primary" data-video="${s.video}">▶ 观看对应仪式影片</button>`:''}<button class="text-link" data-gallery="${key}" data-index="${index}">${s.extras?'查看全部空间设计图':'逐张查看空间过程'} ↗</button></div>`;}
 function renderMedal(i){const m=data.medals[i],key=registerGallery('medal-'+i,m.extras);selected($('.medal-tabs'),i,'medal');$('#medal-stage').setAttribute('aria-labelledby','medal-tab-'+i);$('#medal-stage').innerHTML=`<button class="asset-main" data-gallery="${key}" data-index="0" aria-label="放大${m.name}勋章"><img src="${m.src}" alt="${m.name}勋章正面" loading="lazy"><span>查看完整勋章 ↗</span></button><div class="asset-copy"><span class="eyebrow">0${i+1} / ${m.en}</span><h3>${m.name}</h3><p>${m.desc}</p><dl class="asset-facts"><div><dt>精神表达</dt><dd>${m.meaning}</dd></div><div><dt>视觉构成</dt><dd>${m.color}</dd></div></dl><button class="primary medal-video-button" data-video="coronation">▶ 观看门徒加冕 <small>02:15</small></button><div class="asset-thumbs">${m.extras.slice(1).map((it,j)=>`<button data-gallery="${key}" data-index="${j+1}" aria-label="查看${it.title}"><img src="${it.src}" alt="${it.title}" loading="lazy">${j===0?'多角度设定':'设计图'} ↗</button>`).join('')}</div><span class="asset-count">正面 / 多角度 / 设计图 · 3 张高清素材</span></div>`;}
 function renderObject(i){const o=data.objects[i],key=registerGallery('object-'+i,o.extras);selected($('.object-tabs'),i,'object');$('#object-stage').classList.add('object-stage');$('#object-stage').setAttribute('aria-labelledby','object-tab-'+i);$('#object-stage').innerHTML=`<button class="asset-main" data-gallery="${key}" data-index="0" aria-label="放大${o.name}设定"><img src="${o.src}" alt="${o.name}造型设定" loading="lazy"><span>查看完整设定 ↗</span></button><div class="asset-copy"><span class="eyebrow">${o.en}</span><h3>${o.title}</h3><p>${o.desc}</p><div class="asset-thumbs">${o.extras.slice(1).map((it,j)=>`<button data-gallery="${key}" data-index="${j+1}" aria-label="查看${it.title}"><img src="${it.src}" alt="${it.title}" loading="lazy">${it.title.split(' · ')[1]} ↗</button>`).join('')}</div><span class="asset-count">${o.extras.length} 张高清素材 · 可逐张查看</span></div>`;}
 renderAct(0);renderRoles('realistic','#real-role-grid');renderRoles('cartoon');renderSpace(5);renderMedal(0);renderObject(0);requestAnimationFrame(()=>{const target=document.getElementById(location.hash.slice(1));if(target)target.scrollIntoView({block:'start',behavior:'instant'});updateProgress();});
 renderRealAct(0);
 document.addEventListener('click',e=>{const b=e.target.closest('[data-real-select]');if(b){renderRealAct(Number(b.dataset.realSelect));$('#realistic-story').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}const tab=e.target.closest('[data-real-act]');if(tab)renderRealAct(Number(tab.dataset.realAct));});
 document.addEventListener('click',e=>{const b=e.target.closest('[role=tab]');if(!b)return;if(b.dataset.act!==undefined)renderAct(Number(b.dataset.act));if(b.dataset.roles)renderRoles(b.dataset.roles);if(b.dataset.space!==undefined)renderSpace(Number(b.dataset.space));if(b.dataset.medal!==undefined)renderMedal(Number(b.dataset.medal));if(b.dataset.object!==undefined)renderObject(Number(b.dataset.object));if(b.dataset.route){selected($('.film-route'),b.dataset.route,'route');['cartoon-story','realistic-story'].forEach(id=>$('#'+id).hidden=id!==b.dataset.route);}});
}).catch(()=>{$('#act-panel').innerHTML='<p>内容暂时无法加载，请刷新页面重试。</p>';});
document.addEventListener('keydown',e=>{const b=e.target.closest('[role=tab]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=Array.from(b.closest('[role=tablist]').querySelectorAll('[role=tab]')),i=tabs.indexOf(b),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();tabs[next].scrollIntoView({block:'nearest',inline:'nearest'});});
$('#space-compare').addEventListener('click',()=>{const panel=$('#space-comparison'),open=panel.hidden;panel.hidden=!open;$('#space-compare').setAttribute('aria-pressed',String(open));$('#space-compare').textContent=open?'收起比较 −':'并排比较概念与现场 ⇄';});
$('#script-open').addEventListener('click',async()=>{galleryItems=[];show('创作阶段的原始 16 镜脚本');content.textContent='正在加载脚本…';const revision=mediaRevision;try{const rows=window.OFFLINE_DATA.script;if(!dialog.open||revision!==mediaRevision)return;content.innerHTML='<p class="script-intro">原始创作脚本共 16 镜，合计 60.6 秒；最终卡通成片约 97.8 秒。此处保留创作过程，上方故事章节按最终成片整理。</p>'+rows.map(r=>`<article class="script-row"><div class="shot-number">${esc(r.shot)}<span>${esc(r.duration)}</span></div><div><p class="script-action">${esc(r.action)}</p><div class="script-meta"><div><b>景别 / 运镜</b>${esc(r.camera)}</div><div><b>光影设计</b>${esc(r.light)}</div><div><b>声音意图</b>${esc(r.sound.trim()||'原脚本未填写')}</div></div></div></article>`).join('');}catch{content.textContent='脚本暂时无法加载，请关闭后重试。';}});
const sectionIds=['overview','background','strategy','visual','films','ceremony'];let ticking=false;
function updateProgress(){ticking=false;const max=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.width=`${max>0?scrollY/max*100:0}%`;let active=sectionIds[0];for(const id of sectionIds){if($('#'+id).getBoundingClientRect().top<innerHeight*.4)active=id;}$('.site-header nav').querySelectorAll('a').forEach(a=>{const yes=a.hash==='#'+active;a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}
addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(updateProgress);}}, {passive:true});addEventListener('resize',updateProgress);updateProgress();
